mapper.select:
SELECT id, train_no, seat_no, segment_no, remain, update_time
FROM stock
WHERE instance_no = #{instanceNo}
  AND seat_no = #{seatNo}
ORDER BY segment_no ASC

mapper.update:
UPDATE stock
SET remain      = remain - 1,
    update_time = NOW()
WHERE instance_no = #{instanceNo}
  AND seat_no = #{seatNo}
  AND segment_no = #{segmentNo}
  AND remain > 0
